mapper.select:
SELECT n.id, n.user_id, n.workspace_id, n.type, n.title, n.body, n.ref_task_id, n.ref_kind, n.ref_id, n.req_id, n.read_at, n.created_at, w.name AS workspace_name, ro.display_name AS ref_owner_name FROM app_notification n LEFT JOIN workspace w ON w.id = n.workspace_id
LEFT JOIN version_release_plan vrp ON n.ref_kind = 'release_plan' AND vrp.workspace_id = n.workspace_id AND vrp.id = n.ref_id LEFT JOIN app_user ro ON ro.id = vrp.owner_user_id WHERE n.user_id = #{userId} AND n.workspace_id = #{workspaceId} AND n.read_at IS NULL
ORDER BY n.created_at DESC, n.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM app_notification n
WHERE n.user_id = #{userId}
   AND n.workspace_id = #{workspaceId} 
   AND n.read_at IS NULL

SELECT COUNT(*) FROM app_notification n
WHERE n.user_id = #{userId} AND n.read_at IS NULL
   AND n.workspace_id = #{workspaceId}

SELECT COUNT(*) FROM app_notification n
WHERE n.user_id = #{userId}
   AND n.workspace_id = #{workspaceId}

SELECT COUNT(*) FROM app_notification n
WHERE n.user_id = #{userId} AND n.read_at IS NULL

   AND n.workspace_id = #{workspaceId}

SELECT n.type AS type, COUNT(*) AS cnt
FROM app_notification n
WHERE n.user_id = #{userId}
   AND n.workspace_id = #{workspaceId} 
   AND n.read_at IS NULL 


GROUP BY n.type

